//! Checks audit records emitted by a realistic request sequence against the format
//! contract.
//!
//! The committed fixtures in `lakekeeper` pin the shape of the scenarios they cover, but a
//! fixture is generated by the test that asserts against it — so a wrongly built event
//! produces a fixture that agrees with it, and neither notices. This test instead states
//! rules that hold for *any* audit record and checks them against records produced by
//! going through the real service layer, which reaches paths no fixture exercises.
//!
//! It registers the audit listener on its own `ApiContext` only. The shared test harness
//! deliberately does not register it, so no other test is affected by this file.
//!
//! # This file is meant to grow
//!
//! The rules apply to any record, but only ever see records something emitted — so
//! coverage is exactly the request sequences exercised here, and that set starts small.
//! Widening it is the point: drive another call through `CatalogServer` and the existing
//! rules apply to whatever it produces. Reached today: the authorization family in both its
//! allowed and denied form; the `idempotent_replay` family — which carries `action` and
//! `entity` but no `decision`, so it is the one record here that a consumer keying on
//! `entity` would misread; and the operational family, through the `grant_created` records
//! of a grant change. Views are reached through the owner property rules, refused before
//! and after authorization, and through a register, which records its warehouse right. A
//! second test refuses that right with a blocking test authorizer, for the denied form. A
//! storage profile change records two actions on one warehouse.
//! Not yet reached, cheapest to add first: table commits; several entities in one record;
//! per-decision `id`/`for_principal`/`determined_by`, which need a batch-style check;
//! and a real authorizer with an authenticated actor (`AllowAllAuthorizer` and
//! `random_request_metadata()` reach neither) — the OpenFGA authorizer is the cheap way in,
//! because CI already provisions it.
//!
//! Keep every test here on a current-thread runtime. Capture is thread-local:
//! `set_default` binds the subscriber to the calling thread, and the detached
//! `tokio::spawn` that dispatches audit events has to be polled on that thread to be seen.
//! A second `#[sqlx::test]` is fine — `sqlx_core::rt::test_block_on` builds a fresh
//! `Builder::new_current_thread()` runtime per invocation and cargo runs each test on its
//! own thread, so there is nothing shared to contend for. What breaks capture is
//! `flavor = "multi_thread"`, which lets the dispatch task run on a worker thread that has
//! no default subscriber. `EXPECTED_RECORDS` is what catches that: capture would go to
//! zero, or to some subset, and a count has to be met where "did anything arrive" does not.
//!
//! Adding a case is cheap, and it is two steps: drive another call through `CatalogServer`
//! or `ApiServer` before the wait, and raise `EXPECTED_RECORDS` by however many records it
//! emits. The existing rules then apply to whatever it produced. Run it on its own with
//! `just test-audit-corpus`, which needs the local Postgres from the initial setup — the
//! count is checked there in seconds, so there is no reason to learn about it from CI.
//!
//! A good case is one that reaches a code path no other case here reaches — a new assertion
//! is worth less than a new record shape, because the rules are already general and it is
//! the inputs that are narrow.
//!
//! If you are here because you changed the audit log format, see the audit log section of
//! `docs/docs/developer-guide.md`: extending this file is part of that change.

use std::sync::Arc;

use iceberg::NamespaceIdent;
use lakekeeper::{
    api::{
        RequestMetadata, RequestMetadataTestBuilder,
        iceberg::v1::{
            CommitViewRequest, DataAccess, NamespaceParameters, ViewParameters,
            namespace::NamespaceService as _, tables::TablesService as _, views::ViewService as _,
        },
        management::v1::{
            check::{
                CatalogActionCheckItem, CatalogActionCheckOperation,
                CatalogActionsBatchCheckRequest, RoleAssignee, TabularIdentOrUuid, UserOrRole,
                check_internal,
            },
            grant::{ApplyGrantsRequest, GrantEntry, ListGrantsQuery, Service as _},
            role::Service as _,
            warehouse::{
                Service as _, UpdateWarehouseCredentialRequest, UpdateWarehouseStorageRequest,
            },
        },
    },
    server::CatalogServer,
    service::{
        RoleId, UserId, authn::Actor, authz::AllowAllAuthorizer,
        events::backends::audit::AuditEventListener, idempotency::IdempotencyKey,
    },
};
use lakekeeper_integration_tests::{
    SetupTestCatalog, create_table_request, create_view_request, memory_io_profile,
    random_request_metadata, trino_engine_request, user_request,
};

/// How many audit records the request sequence in the test below emits.
///
/// **Adding or removing a call means updating this number**, and nothing but a failing test
/// will tell you.
///
/// What this cannot do: prove that no *further* record arrives. After the count is reached
/// the test watches for [`SETTLE_WINDOW`] and warns if more turn up, but a record emitted
/// later than that is invisible to it. So the constant is a reliable floor and only a
/// best-effort ceiling.
const EXPECTED_RECORDS: usize = 38;

/// How long to wait for [`EXPECTED_RECORDS`] before failing.
///
/// Generous on purpose: it is reached only when the test is already failing, so a large
/// value costs nothing on a green run and buys tolerance on a loaded machine.
const CAPTURE_DEADLINE: std::time::Duration = std::time::Duration::from_secs(10);

/// How often to re-read while waiting. Short, because each poll is a cheap buffer read and
/// the `await` is what lets the detached dispatch tasks run at all.
const POLL_INTERVAL: std::time::Duration = std::time::Duration::from_millis(25);

/// How long to keep watching after the expected count arrives, to notice an extra record.
///
/// A warning, not a failure: an extra record is not a contract violation — it is checked by
/// the same rules as the others — it just means [`EXPECTED_RECORDS`] is stale.
const SETTLE_WINDOW: std::time::Duration = std::time::Duration::from_millis(250);
use sqlx::PgPool;

#[derive(Clone, Default)]
struct CapturedLogs(Arc<std::sync::Mutex<Vec<u8>>>);

impl std::io::Write for CapturedLogs {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        self.0.lock().expect("log buffer poisoned").extend(buf);
        Ok(buf.len())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

impl tracing_subscriber::fmt::MakeWriter<'_> for CapturedLogs {
    type Writer = Self;
    fn make_writer(&self) -> Self::Writer {
        self.clone()
    }
}

/// Every audit record captured so far, envelope fields stripped.
fn audit_records(logs: &CapturedLogs) -> Vec<serde_json::Value> {
    let bytes = logs.0.lock().expect("log buffer poisoned").clone();
    String::from_utf8(bytes)
        .expect("log output is utf-8")
        .lines()
        .filter_map(|line| serde_json::from_str::<serde_json::Value>(line).ok())
        .filter(|record| record.get("event_source").and_then(|v| v.as_str()) == Some("audit"))
        .map(lakekeeper::audit::validate::contract_fields)
        .collect()
}

#[lakekeeper_storage_postgres::db_test]
async fn audit_records_from_a_real_request_sequence_satisfy_the_contract(pool: PgPool) {
    let logs = CapturedLogs::default();
    // Thread-local, not global: `sqlx::test` runs on a current-thread runtime, so the
    // detached `tokio::spawn` that dispatches audit events is polled on this same thread
    // and sees this subscriber. A global subscriber would race with other test binaries.
    // The binary's log format, so the captured records are shaped like production's.
    let _guard = tracing::subscriber::set_default(
        lakekeeper::audit::log_format(false)
            .with_writer(logs.clone())
            .finish(),
    );

    let (ctx, warehouse_response) = SetupTestCatalog::builder()
        .pool(pool.clone())
        .storage_profile(memory_io_profile())
        .authorizer(AllowAllAuthorizer::default())
        .number_of_warehouses(1)
        .build()
        .setup()
        .await;

    // Only this context emits audit events; the shared harness is untouched.
    ctx.v1_state
        .events
        .append(Arc::new(AuditEventListener::default()))
        .await;

    let warehouse = warehouse_response.warehouse_id.to_string();
    let namespace = NamespaceIdent::from_vec(vec!["audit_corpus".to_string()]).unwrap();

    // A create that succeeds, then a lookup of something absent so a genuine denial or
    // not-found path is exercised too.
    let _ = CatalogServer::create_namespace(
        Some(warehouse.clone().into()),
        iceberg_ext::catalog::rest::CreateNamespaceRequest {
            namespace: namespace.clone(),
            properties: Some(std::collections::HashMap::from([(
                "owner".to_string(),
                "audit-corpus".to_string(),
            )])),
        },
        ctx.clone(),
        random_request_metadata(),
    )
    .await;

    let namespace_params = NamespaceParameters {
        prefix: Some(warehouse.clone().into()),
        namespace: namespace.clone(),
    };

    // A table, which reaches the `create_table` action and its `name` / `table_id` context.
    let created = CatalogServer::create_table(
        namespace_params.clone(),
        create_table_request(Some("audited_table".to_string()), None),
        DataAccess::not_specified(),
        ctx.clone(),
        random_request_metadata(),
    )
    .await;

    // A table created, then dropped twice under one Idempotency-Key. Covers an authorization
    // record with a populated `idempotency_key` (every other record here leaves it out), and
    // the `idempotent_replay` record, which carries `actions` and `entities` but no
    // `decision`. The drop endpoint checks idempotency before authorizing, so the replayed
    // call emits the replay record alone.
    // A key is globally unique, not per endpoint: reusing one across two operations is
    // rejected with `IdempotencyKeyReused`, so the create and the drop get their own.
    let new_key = || {
        IdempotencyKey::parse(&uuid::Uuid::now_v7().to_string())
            .expect("a v7 uuid is a valid idempotency key")
    };
    let keyed_metadata = |key| {
        let mut metadata = random_request_metadata();
        metadata.with_idempotency_key(key);
        metadata
    };
    let drop_key = new_key();
    let replayed_table = || lakekeeper::api::iceberg::v1::TableParameters {
        prefix: Some(warehouse.clone().into()),
        table: iceberg::TableIdent::new(namespace.clone(), "replayed_table".to_string()),
    };
    let drop_params = || lakekeeper::api::iceberg::v1::DropParams {
        purge_requested: true,
        force: false,
    };

    let replayed_created = CatalogServer::create_table(
        namespace_params.clone(),
        create_table_request(Some("replayed_table".to_string()), Some(false)),
        DataAccess::not_specified(),
        ctx.clone(),
        keyed_metadata(new_key()),
    )
    .await;

    if replayed_created.is_ok() {
        let _ = CatalogServer::drop_table(
            replayed_table(),
            drop_params(),
            ctx.clone(),
            keyed_metadata(drop_key),
        )
        .await;

        let _ = CatalogServer::drop_table(
            replayed_table(),
            drop_params(),
            ctx.clone(),
            keyed_metadata(drop_key),
        )
        .await;
    }

    // Loading it reaches `get_metadata` on an entity that carries a table id and location,
    // rather than only a namespace.
    let _ = CatalogServer::load_table(
        lakekeeper::api::iceberg::v1::TableParameters {
            prefix: Some(warehouse.clone().into()),
            table: iceberg::TableIdent::new(namespace.clone(), "audited_table".to_string()),
        },
        lakekeeper::api::iceberg::v1::tables::LoadTableRequest::builder().build(),
        ctx.clone(),
        random_request_metadata(),
    )
    .await;

    // Listing reaches an action whose entity is the namespace but whose result is a set.
    // It still emits the singular `entity` form: arity follows the entities checked, not
    // the rows returned.
    let _ = CatalogServer::list_tables(
        namespace_params.clone(),
        lakekeeper::api::iceberg::v1::ListTablesQuery {
            page_token: lakekeeper::api::iceberg::v1::PageToken::NotSpecified,
            page_size: None,
            return_uuids: true,
            return_protection_status: false,
        },
        ctx.clone(),
        random_request_metadata(),
    )
    .await;

    // A rename into another namespace is recorded as `move`, with the destination
    // namespace as `destination` context; renaming it back is a second `move`.
    let moves_namespace = NamespaceIdent::from_vec(vec!["audit_corpus_moves".to_string()]).unwrap();
    let _ = CatalogServer::create_namespace(
        Some(warehouse.clone().into()),
        iceberg_ext::catalog::rest::CreateNamespaceRequest {
            namespace: moves_namespace.clone(),
            properties: None,
        },
        ctx.clone(),
        random_request_metadata(),
    )
    .await;
    for (from, to) in [
        (namespace.clone(), moves_namespace.clone()),
        (moves_namespace.clone(), namespace.clone()),
    ] {
        let _ = CatalogServer::rename_table(
            Some(warehouse.clone().into()),
            iceberg_ext::catalog::rest::RenameTableRequest {
                source: iceberg::TableIdent::new(from, "audited_table".to_string()),
                destination: iceberg::TableIdent::new(to, "audited_table".to_string()),
            },
            ctx.clone(),
            random_request_metadata(),
        )
        .await;
    }

    // Property updates carry `updated_properties` and `removed_properties`.
    let _ = CatalogServer::update_namespace_properties(
        namespace_params.clone(),
        iceberg_ext::catalog::rest::UpdateNamespacePropertiesRequest {
            removals: Some(vec!["owner".to_string()]),
            updates: Some(std::collections::HashMap::from([(
                "retention".to_string(),
                "30d".to_string(),
            )])),
        },
        ctx.clone(),
        random_request_metadata(),
    )
    .await;

    // A drop with purge, which carries the `purge` context field.
    if created.is_ok() {
        let _ = CatalogServer::drop_table(
            lakekeeper::api::iceberg::v1::TableParameters {
                prefix: Some(warehouse.clone().into()),
                table: iceberg::TableIdent::new(namespace.clone(), "audited_table".to_string()),
            },
            lakekeeper::api::iceberg::v1::DropParams {
                purge_requested: true,
                force: false,
            },
            ctx.clone(),
            random_request_metadata(),
        )
        .await;
    }

    // A role create that succeeds, then one the provider guard refuses after the
    // authorizer allowed the action: that refusal is the request's one denial, a
    // project-entity record with `name`, `requested_provider_id` and
    // `requested_source_id` context and an identity-guard error.
    let project_id = warehouse_response.project_id.clone();
    let role_request =
        |provider: Option<&str>| lakekeeper::api::management::v1::role::CreateRoleRequest {
            name: format!("audited-role-{}", provider.unwrap_or("native")),
            description: None,
            project_id: Some((*project_id).clone()),
            provider_id: provider.map(|p| p.parse().unwrap()),
            source_id: provider.map(|_| "audited".parse().unwrap()),
        };
    let native_role = lakekeeper::api::management::v1::ApiServer::create_role(
        role_request(None),
        ctx.clone(),
        random_request_metadata(),
    )
    .await
    .expect("creating a native role");
    let _ = lakekeeper::api::management::v1::ApiServer::create_role(
        role_request(Some("system")),
        ctx.clone(),
        random_request_metadata(),
    )
    .await;

    // The project-wide grant listing about another principal: `read_subtree_grants` on the
    // project entity, with the subtree scope fields and `self_read` context.
    let _ = lakekeeper::api::management::v1::ApiServer::list_grants(
        ctx.clone(),
        RequestMetadataTestBuilder::builder()
            .actor(Actor::Principal(UserId::new_unchecked("oidc", "alice")))
            .project_id(Some(project_id.clone()))
            .build(),
        ListGrantsQuery {
            principal_user: Some(UserId::new_unchecked("oidc", "bob")),
            principal_role: None,
        },
        lakekeeper::api::iceberg::v1::PaginationQuery::new(
            lakekeeper::api::iceberg::v1::PageToken::Empty,
            None,
        ),
    )
    .await;

    // Views and the owner property rules. Only a trusted engine that owns
    // `trino.run-as-owner` may write it: a create by another authenticated client is refused
    // before authorization (1 denied record), the trusted engine's create is allowed (1). On
    // the resulting view, a commit that sets the property is refused before authorization (1).
    // A commit that changes the view's SQL is authorized, then refused once the stored view
    // shows it holds the property (1 allowed, 1 denied).
    let definer_view_request = || {
        let mut request = create_view_request(Some("definer_view"), None);
        request
            .properties
            .insert("trino.run-as-owner".to_string(), "alice".to_string());
        request
    };
    let mut definer_view_metadata = None;
    for request_metadata in [user_request(), trino_engine_request()] {
        if let Ok(created) = CatalogServer::create_view(
            namespace_params.clone(),
            definer_view_request(),
            ctx.clone(),
            DataAccess::not_specified(),
            request_metadata,
        )
        .await
        {
            definer_view_metadata = Some(created.metadata);
        }
    }
    let definer_view = || ViewParameters {
        prefix: Some(warehouse.clone().into()),
        view: iceberg::TableIdent::new(namespace.clone(), "definer_view".to_string()),
    };
    let view_commit = |updates: serde_json::Value| -> CommitViewRequest {
        serde_json::from_value(serde_json::json!({ "updates": updates }))
            .expect("a valid view commit")
    };
    let _ = CatalogServer::commit_view(
        definer_view(),
        view_commit(serde_json::json!([
            {"action": "set-properties", "updates": {"trino.run-as-owner": "bob"}}
        ])),
        ctx.clone(),
        DataAccess::not_specified(),
        user_request(),
    )
    .await;
    let _ = CatalogServer::commit_view(
        definer_view(),
        view_commit(serde_json::json!([
            {
                "action": "add-view-version",
                "view-version": {
                    "version-id": 2,
                    "schema-id": 0,
                    "timestamp-ms": chrono::Utc::now().timestamp_millis(),
                    "summary": {"engine-name": "spark"},
                    "representations": [
                        {"type": "sql", "sql": "select 1", "dialect": "spark"}
                    ],
                    "default-namespace": []
                }
            },
            {"action": "set-current-view-version", "view-version-id": -1}
        ])),
        ctx.clone(),
        DataAccess::not_specified(),
        user_request(),
    )
    .await;

    // Replacing the view, as the OPA bridge asks for Trino, for a user other than its owner:
    // one `introspect_permissions` record with one decision, recorded as `commit` (1). Then
    // the trusted engine switches the view to run as the caller: the commit's record and the
    // `change_security_mode` record of the identity that sends it (2). Switching it back to
    // run as its owner adds the owner's own `change_security_mode` record (3).
    let _ = check_internal(
        ctx.clone(),
        random_request_metadata(),
        CatalogActionsBatchCheckRequest {
            checks: vec![CatalogActionCheckItem {
                id: Some("replace".to_string()),
                identity: Some(UserOrRole::User(UserId::new_unchecked("oidc", "bob"))),
                operation: CatalogActionCheckOperation::ViewReplace {
                    view: TabularIdentOrUuid::Name {
                        namespace: namespace.clone(),
                        table: "definer_view".to_string(),
                        warehouse_id: warehouse_response.warehouse_id,
                    },
                },
            }],
            error_on_not_found: false,
        },
    )
    .await;
    let _ = CatalogServer::commit_view(
        definer_view(),
        view_commit(serde_json::json!([
            {"action": "remove-properties", "removals": ["trino.run-as-owner"]}
        ])),
        ctx.clone(),
        DataAccess::not_specified(),
        trino_engine_request(),
    )
    .await;
    let _ = CatalogServer::commit_view(
        definer_view(),
        view_commit(serde_json::json!([
            {"action": "set-properties", "updates": {"trino.run-as-owner": "bob"}}
        ])),
        ctx.clone(),
        DataAccess::not_specified(),
        trino_engine_request(),
    )
    .await;

    // Registering a view from an existing metadata file: `register_view` on the warehouse and
    // `create_view` with the `view_id` from the file, both allowed (2). A file with the owner
    // property, registered by a client that is not a trusted engine: both allowed, then the
    // `create_view` refused after authorization (3).
    let definer_view_metadata =
        definer_view_metadata.expect("the trusted engine creates definer_view");
    let (view_parent, _) = definer_view_metadata
        .location()
        .rsplit_once('/')
        .expect("a view location has a parent");
    let mut registered_view_ids = std::collections::BTreeMap::new();
    for (name, keep_owner_property, request_metadata) in [
        ("registered_view", false, random_request_metadata()),
        ("registered_definer_view", true, user_request()),
    ] {
        let (metadata_location, view_uuid) = write_view_metadata_copy(
            &definer_view_metadata,
            &format!("{view_parent}/{name}"),
            keep_owner_property,
        )
        .await;
        registered_view_ids.insert(name, view_uuid.to_string());
        let _ = CatalogServer::register_view(
            namespace_params.clone(),
            iceberg_ext::catalog::rest::RegisterViewRequest::builder()
                .name(name.to_string())
                .metadata_location(metadata_location)
                .build(),
            ctx.clone(),
            DataAccess::not_specified(),
            request_metadata,
        )
        .await;
    }

    // A request that writes several records under one `request_id`: a grant change of two
    // grants writes its `apply_grants` record plus one `grant_created` record per grant. The
    // `event_id` rule below needs it.
    let other_role = lakekeeper::api::management::v1::ApiServer::create_role(
        lakekeeper::api::management::v1::role::CreateRoleRequest {
            name: "audited-role-grantee".to_string(),
            ..role_request(None)
        },
        ctx.clone(),
        random_request_metadata(),
    )
    .await
    .expect("creating a second native role");
    let mut granting = RequestMetadata::test_user(UserId::new_unchecked("oidc", "alice"));
    granting.with_project_id((*project_id).clone());
    let grant = |role: RoleId| GrantEntry {
        privilege: "get_metadata".to_string(),
        principal: UserOrRole::Role(RoleAssignee::from_role(role)),
    };
    lakekeeper::api::management::v1::ApiServer::apply_warehouse_grants(
        warehouse_response.warehouse_id,
        ctx.clone(),
        granting,
        ApplyGrantsRequest {
            writes: vec![grant(native_role.id), grant(other_role.id)],
            deletes: Vec::new(),
        },
    )
    .await
    .expect("granting to both roles");

    // Replacing the storage credential records `update_storage_credential`. Changing the
    // storage profile also replaces the credential, so its record carries both actions.
    let _ = lakekeeper::api::management::v1::ApiServer::update_storage_credential(
        warehouse_response.warehouse_id,
        UpdateWarehouseCredentialRequest {
            new_storage_credential: None,
        },
        ctx.clone(),
        random_request_metadata(),
    )
    .await;
    let _ = lakekeeper::api::management::v1::ApiServer::update_storage(
        warehouse_response.warehouse_id,
        UpdateWarehouseStorageRequest {
            storage_profile: memory_io_profile(),
            storage_credential: None,
        },
        ctx.clone(),
        random_request_metadata(),
    )
    .await;

    // Finally a lookup of something absent, so a genuine denial is in the corpus too.
    let _ = CatalogServer::namespace_exists(
        NamespaceParameters {
            prefix: Some(warehouse.clone().into()),
            namespace: NamespaceIdent::from_vec(vec!["does_not_exist".to_string()]).unwrap(),
        },
        ctx.clone(),
        random_request_metadata(),
    )
    .await;

    // Wait for the expected number rather than for a fixed interval. See EXPECTED_RECORDS.
    let deadline = std::time::Instant::now() + CAPTURE_DEADLINE;
    let mut records = audit_records(&logs);
    while records.len() < EXPECTED_RECORDS && std::time::Instant::now() < deadline {
        tokio::time::sleep(POLL_INTERVAL).await;
        records = audit_records(&logs);
    }

    assert!(
        records.len() >= EXPECTED_RECORDS,
        "expected {EXPECTED_RECORDS} audit records from this request sequence, captured \
         {} within {CAPTURE_DEADLINE:?}.\n\n\
         If you ADDED a call above, or one you added emits more than you thought: raise \
         EXPECTED_RECORDS to match. If you REMOVED a call: lower it. The constant is the \
         only thing that notices a request silently stopping emitting, so it has to be \
         maintained by hand — see its doc comment.\n\n\
         If you changed neither, this is the real failure the constant exists to catch: \
         something that used to emit an audit record no longer does. Capture can also \
         fail wholesale — a listener not registered on this context, or a runtime that \
         is not current-thread (see this file's header).\n\n\
         What did arrive:\n{}",
        records.len(),
        describe(&records),
    );

    // Everything expected is here. Keep watching briefly: an extra record means the count
    // above is stale, and it is better to hear about it than to have it pass unmentioned.
    tokio::time::sleep(SETTLE_WINDOW).await;
    let settled = audit_records(&logs);
    if settled.len() > EXPECTED_RECORDS {
        eprintln!(
            "\n!! audit corpus: WARNING — {} record(s) arrived, EXPECTED_RECORDS says \
             {EXPECTED_RECORDS}. The extra ones are checked below, so nothing is wrong with \
             the contract, but the constant is stale: raise it to {}. Extras that arrive \
             later than {SETTLE_WINDOW:?} are not detected at all, so treat this as a \
             lower bound.\n{}\n",
            settled.len(),
            settled.len(),
            describe(&settled),
        );
    }
    let records = settled;

    let committed_schema: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(
            std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../docs/docs/audit/schema.json"),
        )
        .expect("the committed audit schema; generate it with `just update-audit-schema`"),
    )
    .expect("the committed schema is JSON");
    for (index, record) in records.iter().enumerate() {
        lakekeeper::audit::validate::assert_valid_record(
            &committed_schema,
            record,
            &format!("record {index}"),
        );
    }

    // The two renames across namespaces, each a `move` naming its destination namespace.
    let mut moves = records
        .iter()
        .flat_map(|record| record["actions"].as_array().cloned().unwrap_or_default())
        .filter(|action| action["action_name"] == "move")
        .collect::<Vec<_>>();
    moves.sort_by_key(ToString::to_string);
    assert_eq!(
        moves,
        vec![
            serde_json::json!({"action_name": "move", "destination": ["audit_corpus"]}),
            serde_json::json!({"action_name": "move", "destination": ["audit_corpus_moves"]}),
        ],
        "move records:\n{}",
        describe(&records)
    );

    // The owner property refusals: two property writes refused before authorization, one
    // registered file's property refused after it, and one version change refused after it.
    let mut owner_refusals = records
        .iter()
        .filter_map(|record| record["error"]["type"].as_str())
        .filter(|error_type| error_type.starts_with("Protected"))
        .collect::<Vec<_>>();
    owner_refusals.sort_unstable();
    assert_eq!(
        owner_refusals,
        vec![
            "ProtectedPropertyModification",
            "ProtectedPropertyModification",
            "ProtectedPropertyModification",
            "ProtectedViewVersionChange",
        ],
        "owner property refusals:\n{}",
        describe(&records)
    );

    // Each register records `register_view` on the warehouse, without context, and
    // `create_view` with the `view_id` from the file: allowed on both, and refused after
    // authorization on the file with the owner property.
    let actions_named = |action_name: &str| {
        records
            .iter()
            .flat_map(|record| {
                let decision = record["decision"].as_str().unwrap_or("-").to_string();
                record["actions"]
                    .as_array()
                    .cloned()
                    .unwrap_or_default()
                    .into_iter()
                    .map(move |action| (decision.clone(), action))
            })
            .filter(|(_, action)| action["action_name"] == action_name)
            .collect::<Vec<_>>()
    };
    assert_eq!(
        actions_named("register_view"),
        vec![
            (
                "allowed".to_string(),
                serde_json::json!({"action_name": "register_view"})
            ),
            (
                "allowed".to_string(),
                serde_json::json!({"action_name": "register_view"})
            ),
        ],
        "register_view records:\n{}",
        describe(&records)
    );
    let mut registered_view_decisions = actions_named("create_view")
        .into_iter()
        .filter(|(_, action)| action.get("view_id").is_some())
        .map(|(decision, action)| {
            (
                action["name"].as_str().unwrap_or("-").to_string(),
                decision,
                action["view_id"].as_str().unwrap_or("-").to_string(),
            )
        })
        .collect::<Vec<_>>();
    // Separate dispatch tasks write the records, so they may arrive in any order.
    registered_view_decisions.sort();
    let expected = |name: &str, decision: &str| {
        (
            name.to_string(),
            decision.to_string(),
            registered_view_ids[name].clone(),
        )
    };
    assert_eq!(
        registered_view_decisions,
        vec![
            expected("registered_definer_view", "allowed"),
            expected("registered_definer_view", "denied"),
            expected("registered_view", "allowed"),
        ],
        "create_view records with view_id:\n{}",
        describe(&records)
    );

    // The version change was refused after the request was authorized: its denial and the
    // allowed record of the same request share one request id.
    let version_refusal = records
        .iter()
        .find(|record| record["error"]["type"] == "ProtectedViewVersionChange")
        .expect("the version change refusal is checked above");
    let mut same_request = records
        .iter()
        .filter(|record| record["request_id"] == version_refusal["request_id"])
        .map(|record| record["decision"].as_str().unwrap_or("-"))
        .collect::<Vec<_>>();
    same_request.sort_unstable();
    assert_eq!(
        same_request,
        vec!["allowed", "denied"],
        "records of the refused version change:\n{}",
        describe(&records)
    );

    // Every record has its own `event_id`, records of one request included. A rule that
    // holds trivially when no two records share a request proves nothing, so that case has
    // to be in the corpus.
    let mut event_ids = std::collections::HashSet::new();
    for (index, record) in records.iter().enumerate() {
        let event_id = record["event_id"]
            .as_str()
            .unwrap_or_else(|| panic!("record {index} has no `event_id`:\n{}", describe(&records)));
        assert!(
            event_ids.insert(event_id),
            "record {index} repeats `event_id` {event_id}:\n{}",
            describe(&records)
        );
    }
    // The grant change: its `apply_grants` record and one `grant_created` record per grant,
    // all under one `request_id`.
    let grant_request_id = records
        .iter()
        .find(|record| record["actions"][0]["action_name"] == "apply_grants")
        .and_then(|record| record["request_id"].as_str())
        .unwrap_or_else(|| panic!("no `apply_grants` record:\n{}", describe(&records)));
    assert_eq!(
        records
            .iter()
            .filter(|record| record["request_id"] == grant_request_id)
            .count(),
        3,
        "records of the grant change, which the `event_id` rule above needs:\n{}",
        describe(&records)
    );

    eprintln!("audit corpus: {} record(s) checked", records.len());
}

/// Writes a copy of `template` as another view at `view_location`: a new view UUID, and without
/// the owner property unless `keep_owner_property`. Returns the metadata file's location and
/// the view UUID.
async fn write_view_metadata_copy(
    template: &iceberg::spec::ViewMetadata,
    view_location: &str,
    keep_owner_property: bool,
) -> (String, uuid::Uuid) {
    let view_uuid = uuid::Uuid::now_v7();
    let mut metadata = serde_json::to_value(template).expect("view metadata serializes");
    metadata["view-uuid"] = serde_json::json!(view_uuid);
    metadata["location"] = serde_json::json!(view_location);
    if !keep_owner_property {
        metadata["properties"]
            .as_object_mut()
            .expect("view properties")
            .remove("trino.run-as-owner");
    }
    let metadata_location = format!("{view_location}/metadata/00000-registered.metadata.json");
    let storage = memory_io_profile()
        .file_io(None)
        .await
        .expect("in-memory storage");
    lakekeeper_io::LakekeeperStorage::write(
        &storage,
        &metadata_location,
        serde_json::to_vec(&metadata).expect("JSON").into(),
    )
    .await
    .expect("write the metadata file");
    (metadata_location, view_uuid)
}

/// A view register refused on the warehouse, under an authorizer that refuses only
/// `register_view`. The allow-all corpus above cannot produce it. Its two records, a refused
/// `register_view` on the warehouse and a refused `create_view` on the namespace, must match the
/// committed schema, and the `create_view` names the view by the requested name only.
#[lakekeeper_storage_postgres::db_test]
async fn audit_records_of_a_view_register_refused_on_the_warehouse_satisfy_the_contract(
    pool: PgPool,
) {
    use lakekeeper::service::authz::{CatalogWarehouseAction, tests::HidingAuthorizer};

    let logs = CapturedLogs::default();
    // Thread-local, as in the corpus above.
    let _guard = tracing::subscriber::set_default(
        lakekeeper::audit::log_format(false)
            .with_writer(logs.clone())
            .finish(),
    );
    let authz = HidingAuthorizer::new();
    let (ctx, warehouse_response) = SetupTestCatalog::builder()
        .pool(pool.clone())
        .storage_profile(memory_io_profile())
        .authorizer(authz.clone())
        .number_of_warehouses(1)
        .build()
        .setup()
        .await;
    ctx.v1_state
        .events
        .append(Arc::new(AuditEventListener::default()))
        .await;
    let warehouse = warehouse_response.warehouse_id.to_string();
    let namespace = NamespaceIdent::from_vec(vec!["audit_corpus".to_string()]).unwrap();
    CatalogServer::create_namespace(
        Some(warehouse.clone().into()),
        iceberg_ext::catalog::rest::CreateNamespaceRequest {
            namespace: namespace.clone(),
            properties: None,
        },
        ctx.clone(),
        random_request_metadata(),
    )
    .await
    .expect("create the namespace");
    let namespace_params = NamespaceParameters {
        prefix: Some(warehouse.clone().into()),
        namespace,
    };
    let template = CatalogServer::create_view(
        namespace_params.clone(),
        create_view_request(Some("template"), None),
        ctx.clone(),
        DataAccess::not_specified(),
        random_request_metadata(),
    )
    .await
    .expect("create the template view");
    let (view_parent, _) = template
        .metadata
        .location()
        .rsplit_once('/')
        .expect("a view location has a parent");
    let (metadata_location, _) = write_view_metadata_copy(
        &template.metadata,
        &format!("{view_parent}/registered_view"),
        false,
    )
    .await;

    authz.block_action(&format!(
        "warehouse:{:?}",
        CatalogWarehouseAction::RegisterView
    ));
    CatalogServer::register_view(
        namespace_params,
        iceberg_ext::catalog::rest::RegisterViewRequest::builder()
            .name("registered_view".to_string())
            .metadata_location(metadata_location)
            .build(),
        ctx.clone(),
        DataAccess::not_specified(),
        random_request_metadata(),
    )
    .await
    .expect_err("register_view is refused");

    // The namespace and the template view write one record each, the refusal two.
    let expected_records = 4;
    let deadline = std::time::Instant::now() + CAPTURE_DEADLINE;
    let mut records = audit_records(&logs);
    while records.len() < expected_records && std::time::Instant::now() < deadline {
        tokio::time::sleep(POLL_INTERVAL).await;
        records = audit_records(&logs);
    }
    tokio::time::sleep(SETTLE_WINDOW).await;
    let records = audit_records(&logs);
    assert_eq!(
        records.len(),
        expected_records,
        "records:\n{}",
        describe(&records)
    );

    let committed_schema: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(
            std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../docs/docs/audit/schema.json"),
        )
        .expect("the committed audit schema; generate it with `just update-audit-schema`"),
    )
    .expect("the committed schema is JSON");
    for (index, record) in records.iter().enumerate() {
        lakekeeper::audit::validate::assert_valid_record(
            &committed_schema,
            record,
            &format!("record {index}"),
        );
    }

    let mut refusals = records
        .iter()
        .filter(|record| record["decision"] == "denied")
        .map(|record| {
            (
                record["actions"].clone(),
                record["error"]["type"].as_str().unwrap_or("-").to_string(),
            )
        })
        .collect::<Vec<_>>();
    refusals.sort_by_key(|(actions, _)| actions.to_string());
    assert_eq!(
        refusals,
        vec![
            (
                serde_json::json!([{
                    "action_name": "create_view",
                    "name": "registered_view",
                    "properties": {}
                }]),
                "WarehouseActionForbidden".to_string(),
            ),
            (
                serde_json::json!([{"action_name": "register_view"}]),
                "WarehouseActionForbidden".to_string(),
            ),
        ],
        "refused records:\n{}",
        describe(&records)
    );
}

/// One line per record, enough to tell which call produced it. For failure messages: a raw
/// dump of seven full records buries the one thing the reader needs, which is what is missing.
fn describe(records: &[serde_json::Value]) -> String {
    records
        .iter()
        .enumerate()
        .map(|(index, record)| {
            let field = |name: &str| {
                record
                    .get(name)
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("-")
                    .to_string()
            };
            // The first action is enough to recognise the call.
            let action = record
                .get("actions")
                .and_then(serde_json::Value::as_array)
                .and_then(|actions| actions.first())
                .and_then(|action| action.get("action_name"))
                .and_then(serde_json::Value::as_str)
                .unwrap_or("-");
            format!(
                "  {index}: action={action} decision={} operation={}",
                field("decision"),
                field("operation"),
            )
        })
        .collect::<Vec<_>>()
        .join("\n")
}
